-- Copy the non-political findings that existed only inside the 10-check rows (bot payloads read by check_findings)
-- into the Legal section, before the check rows are deleted. Approved by Alex 2026-10-28 10:42 PT.
-- Values are taken as-is from the submission payload fields (title/caption, year, status, summary, court, source URL).
-- Skipped: 689 political-ties findings (owner: skip), and 15 rows that were duplicates (same case already in Legal
-- for that firm, or the same case twice in the payload), or not a finding (firm not a party).
-- Source URLs go through the normal sources + fact_sources link, like promote_bot_facts.
create temporary table _chk_copy (firm_id uuid, slug text, grp text, title text, year_label text, state text, status_label text,
  note text, stable_key text, url text, src_label text) on commit drop;
with ins as (
  select md5('check-copy:' || c.firm_id || ':' || c.url || ':' || c.title)::uuid, c.firm_id, c.grp, c.title, c.year_label, c.state,
         c.status_label, c.note,
         1000 + row_number() over (partition by c.firm_id order by c.year_label desc nulls last, c.title)::int, false
    from (select distinct on (firm_id, public._legal_key(title)) * from _chk_copy order by firm_id, public._legal_key(title), url) c
    join public.firms f on f.id = c.firm_id and f.deleted_at is null
   where not exists (select 1 from public.firm_legal_items l where l.firm_id = c.firm_id and l.stable_key = public._legal_key(c.title))
  on conflict (id) do nothing
  returning id, firm_id)
select count(*) from ins;

select distinct on (c.url) c.url, substring(c.url from '://(?:www\.)?([^/]+)'), coalesce(c.src_label, substring(c.url from '://(?:www\.)?([^/]+)')), now(), 'real', 'check_copy'
  from _chk_copy c where c.url ~* '^https?://'
on conflict (url) do nothing;

select md5(l.id || ':' || c.url)::uuid, s.id, c.firm_id, 'firm_legal_items', l.id,
       coalesce(c.src_label, substring(c.url from '://(?:www\.)?([^/]+)')), to_char(now() at time zone 'America/Los_Angeles', 'YYYY-MM-DD'), 0, 'real'
  from _chk_copy c
  join public.firm_legal_items l on l.id = md5('check-copy:' || c.firm_id || ':' || c.url || ':' || c.title)::uuid
  join public.sources s on s.url = c.url
on conflict (id) do nothing;
